fn days_to_next_sunday(day: &str) -> i8 {
    // Map each day to its index where Sunday is 0
    let day_index = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        _ => panic!("Invalid day abbreviation"),
    };

    // Compute days until next Sunday
    7 - day_index
}